<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('services.view');
$pageTitle='Mis vencimientos';$user=current_user();$days=parse_alert_days((string)($user['alert_days']??'1'));$max=max($days);
$stmt=db()->prepare("SELECT s.*,c.company_name,c.email client_email,c.whatsapp FROM client_services s JOIN clients c ON c.id=s.client_id WHERE s.status='active' AND c.status<>'inactive' AND s.expiration_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL ? DAY) ORDER BY s.expiration_date,c.company_name");$stmt->execute([$max]);$services=$stmt->fetchAll();
require __DIR__.'/includes/header.php';
?>
<section class="panel"><div class="panel-header"><div><h2>Vencimientos según mis alertas</h2><span class="table-sub">Canales: <?=$user['notify_email']?'Email ':''?><?=$user['notify_whatsapp']?'· WhatsApp ':''?><?=$user['notify_inapp']?'· CRM':''?> · Anticipación: <?=e(implode(', ',$days))?> día(s).</span></div><a class="btn btn-light btn-small" href="profile.php">Configurar alertas</a></div><div class="table-wrap">
<?php if(!$services):?><div class="empty">No hay vencimientos dentro de tu ventana de alerta.</div><?php else:?><table class="data-table"><thead><tr><th>Cliente / servicio</th><th>Vencimiento</th><th>Pago</th><th>Contacto</th><th></th></tr></thead><tbody><?php foreach($services as$s):$d=days_until($s['expiration_date']);?><tr><td><a class="table-title" href="client_view.php?id=<?=(int)$s['client_id']?>"><?=e($s['company_name'])?></a><span class="table-sub"><?=e($s['name'])?></span></td><td><?=e(format_date($s['expiration_date']))?><span class="table-sub"><?=$d===0?'Hoy':'En '.$d.' días'?></span></td><td><span class="badge badge-<?=e(payment_status_class((string)($s['payment_status']??'pending')))?>"><?=e(payment_status_label((string)($s['payment_status']??'pending')))?></span></td><td><div class="icon-actions"><?php if($s['client_email']):?><a class="icon-action contact-icon email" title="Enviar email" href="mailto:<?=e($s['client_email'])?>"><?=crm_icon('mail')?></a><?php endif;?><?php if($s['whatsapp']):?><a class="icon-action contact-icon whatsapp" title="Abrir WhatsApp" target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D+/','',$s['whatsapp']))?>"><?=crm_icon('whatsapp')?></a><?php endif;?></div></td><td><a class="btn btn-light btn-small" href="service_renew.php?id=<?=(int)$s['id']?>">Revisar</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
